const body = $input.first().json.body;
if (!body || body.object !== 'page') return [];
const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    if (!msg.message || msg.message.is_echo || !msg.message.text) continue;
    out.push({ json: { psid: msg.sender.id, text: msg.message.text.trim() } });
  }
}
return out;

const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;
const search = $('DG Search').first().json || {};
const products = (search.products || []).slice(0, 5);
const faqs = (search.faqs || []).slice(0, 3);
const histRows = $('Get History').all().map(r => r.json).reverse();
const histText = histRows.slice(0, -1).map(h => (h.role === 'user' ? 'Хэрэглэгч' : 'Туслах') + ': ' + h.content).join('\n');
const fmt = (n) => Number(n).toLocaleString('mn-MN') + '₮';
const prodText = products.length > 0
  ? products.map((p, i) => {
      const priceLine = p.salePrice != null
        ? `Хямдарсан үнэ: ${fmt(p.salePrice)} (хуучин ${fmt(p.price)})`
        : `Үнэ: ${fmt(p.price)}`;
      return `${i+1}. ${p.title}\nТөрөл: ${p.productType}\n${priceLine}\nЛинк: ${p.url}\nЗураг: ${p.imageUrl || 'байхгүй'}\nТайлбар: ${p.description}\nЯагаад тохирсон: ${p.matchReason}`;
    }).join('\n\n')
  : 'Тохирох бүтээгдэхүүн олдсонгүй.';
const faqText = faqs.length > 0
  ? faqs.map((f, i) => `${i+1}. Асуулт: ${f.question}\nХариулт: ${f.answer}`).join('\n\n')
  : 'Холбогдох түгээмэл асуулт олдсонгүй.';
const nothingFound = products.length === 0 && faqs.length === 0;
return [{ json: { psid, userText, prodText, faqText, histText, nothingFound } }];

