try {
  reply = $input.first().json.candidates[0].content.parts[0].text.trim();
} catch(e) {
  reply = 'Уучлаарай, түр хүлээгээд дахин оролдоно уу.';
}
if (reply.length > 1000) reply = reply.slice(0, 990) + '...';
return [{ json: { psid, reply } }];

